<section class="panel"><h2>Schools on your platform</h2><p class="muted">Select a school to work in its isolated workspace.</p><div class="table-wrap"><table><thead><tr><th>School</th><th>Students</th><th>Currency</th><th>Status</th><th>Workspace</th><th>Access</th></tr></thead><tbody><?php if(!$schools) emptyRow(6,'Create your first school below.'); foreach($schools as $s): ?><tr><td><strong><?= e($s['name']) ?></strong><small><?= e($s['email']) ?></small></td><td><?= e($s['student_count']) ?></td><td><?= e($s['currency']) ?></td><td><?php badge($s['active']?'Active':'Inactive'); ?></td><td><?php if($s['active']): startForm('school.select',['school_id'=>$s['id'],'next'=>$next],'inline'); ?><button class="button primary">Open workspace →</button></form><?php endif ?></td><td><?php startForm('school.toggle',['id'=>$s['id']],'inline'); ?><button class="button" data-confirm="Change access for every user in this school?"><?= $s['active']?'Deactivate':'Activate' ?></button></form></td></tr><?php endforeach ?></tbody></table></div></section><section class="panel"><h2>＋ Add a school</h2><p class="muted">Each school starts with configurable Day Scholar and Boarding Student types and five school roles.</p><?php startForm('school.create'); field('name','School name'); endForm('Create school'); ?></section>
